    helm_icon_t id;
    uint8_t ink_w;
    uint8_t cx_off;
    int8_t dot_dx;
    lv_obj_t * ico;
    lv_obj_t * dot;
    uint8_t tone_last;
    uint8_t dot_last;   /**< 0=隐藏 1=实心 2=空心 */
