/* ── 小工具 ─────────────────────────────────────────────────────────── */

static lv_color_t sb_tone_color(sb_tone_t tone)
{
    switch (tone) {
    case SB_TONE_INK:
        return helm_color(HELM_COLOR_INK);
    case SB_TONE_RED:
        return helm_color(HELM_COLOR_GPS_DEAD);
    case SB_TONE_BLUE:
        return helm_color(HELM_COLOR_BAN_NAV);
    case SB_TONE_TRACK:
    default:
        return helm_color(HELM_COLOR_TRACK);
    }
}

