                                   bool hr, bool pwr, bool cad, bool rec,
                                   bool nav)
{
    uint32_t key = (uint32_t)(time_ink_w & 0x3F);

    key = key * 2u + (ble ? 1u : 0u);
    key = key * 2u + (hr ? 1u : 0u);
    key = key * 2u + (pwr ? 1u : 0u);
    key = key * 2u + (cad ? 1u : 0u);
    key = key * 2u + (rec ? 1u : 0u);
    key = key * 2u + (nav ? 1u : 0u);

