static void sb_battery_update(void)
{
    const int inner = SB_BATT_BODY_W - 2;   /* 只扣 1px 边框：填充贴边框 */
    int pct = s_battery_pct;
    int w;

    if (pct < 0) {
        w = 0;
    } else {
        if (pct > 100) {
            pct = 100;
        }
        w = inner * pct / 100;
        if (w < 1 && pct > 0) {
            w = 1;
        }
    }

    /* 自绘电池：只改填充宽度；颜色由 sb_slot_apply(SB_BAT) 按 tone 上。 */
    if (s_batt_fill != NULL) {
        lv_obj_set_width(s_batt_fill, w);
    }
}

