static const tour_step_t * s_steps = kSteps;
static int s_step_count = TOUR_STEP_COUNT_DEFAULT;

static struct {
    bool configured;
    bool started;
    bool done;
    bool failed;
    char dir[480];
    int frames;
    int step;
    int waited;
    int nav_wait;
    int boot_wait;
    lv_timer_t *tmr;
} s_tour;

/** R1-S10：巡页期间要"盖住"板级传感器桩的注入值（0 = 不注入）。
 *  板级桩每 10 ms 把 128/84 写回 runtime；巡页定时器比它晚创建，所以在
 *  同一拍里后写、并在下一拍 500 ms 刷新前保持住。 */
static int s_tour_hr_bpm;
static int s_tour_cad_rpm;

static const char *tour_page_name(int id)
{
    switch (id) {
        case BICYCLE_PM_ID_MAP:          return "map";
        case BICYCLE_PM_ID_USB_TRANSFER: return "usb_transfer";
        case BICYCLE_PM_ID_STARTUP:      return "startup";
        case BICYCLE_PM_ID_MENU:         return "menu";
        case BICYCLE_PM_ID_FACTORY:      return "factory";
        default:                         return "?";
    }
}

static void tour_log(const char *fmt, ...)
{
    va_list ap;

    fputs("[tour] ", stdout);
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    fputc('\n', stdout);
    fflush(stdout);
}

static void tour_finish(void);

/** `mkdir -p`：逐级建目录（已存在不算错）。 */
static bool tour_mkdir_p(const char *dir)
{
    char tmp[sizeof(s_tour.dir)];
    size_t len = strlen(dir);

    if (len == 0 || len >= sizeof(tmp)) {
        return false;
    }
    memcpy(tmp, dir, len + 1);

    for (char *p = tmp + 1; *p; p++) {
        if (*p != '/') {
            continue;
        }
        *p = '\0';
        if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
            return false;
        }
        *p = '/';
    }
    if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
        return false;
    }
    return true;
}

/** 整屏失效后同步刷一遍，把影子缓冲补成完整一帧，再写 PNG。 */
static void tour_take_shot(const char *name)
{
    char path[sizeof(s_tour.dir) + 64];
    const uint16_t *fb;
    int w = 0;
    int h = 0;

    lv_obj_invalidate(lv_screen_active());
    lv_refr_now(NULL);

    fb = sim_display_shadow(&w, &h);
    if (snprintf(path, sizeof(path), "%s/%s.png", s_tour.dir, name) >= (int)sizeof(path)) {
        fprintf(stderr, "[tour] path too long: %s/%s.png\n", s_tour.dir, name);
        s_tour.failed = true;
        tour_finish();
        return;
    }

    if (sim_png_write(path, fb, w, h)) {
        tour_log("shot %s (%dx%d) page=%s theme=%s tick=%u", path, w, h,
                 tour_page_name((int)lvgl_page_current_id()),
                 lvgl_page_theme_name(), (unsigned)lv_tick_get());
        /* 地图页的米/像素：比例尺显隐的判据（helm_shell.c 的 mpp > 0）。 */
        if (lvgl_page_current_id() == BICYCLE_PM_ID_MAP && lvgl_page_map() != NULL) {
            tour_log("  map mpp=%.3f m/px (scale bar shown when > 0)",
                     map_page_map_mpp(lvgl_page_map()));
        }
    } else {
        fprintf(stderr, "[tour] shot FAILED %s\n", path);
        s_tour.failed = true;
        tour_finish();
    }
}

/** 开机结束的判据：splash 已 pop、无转场在跑、LiveMap 实例已建。 */
static bool tour_boot_ready(void)
{
    bicycle_pm_id_t id = lvgl_page_current_id();

    if (lv_pm_nav_busy()) {
        return false;
    }
    if (id == BICYCLE_PM_ID_STARTUP) {
        return false;
    }
    return lvgl_page_map() != NULL;
}

static void tour_next_step(void)
{
    s_tour.step++;
    s_tour.waited = 0;
    s_tour.nav_wait = 0;
}

static void tour_finish(void)
{
    s_tour.done = true;
    sim_ui_mtp_force_attached = false;
    if (s_tour.tmr) {
        lv_timer_delete(s_tour.tmr);
        s_tour.tmr = NULL;
    }
    tour_log("%s (dir=%s, frames=%d)", s_tour.failed ? "done WITH ERRORS" : "done",
             s_tour.dir, s_tour.frames);
    tour_log("note: page_factory skipped (CONFIG_MYVENDOR_FACTORY_MODE off in sim)");
}

static void tour_tick_cb(lv_timer_t *tmr)
{
    (void)tmr;

    if (!s_tour.started || s_tour.done || s_tour.failed) {
        return;
    }
    if (s_tour.step < 0 || s_tour.step >= s_step_count) {
        tour_finish();
        return;
    }

    const tour_step_t *st = &s_steps[s_tour.step];

    /* R1-S10：传感器桩每 10 ms 写回 128/84；本定时器后创建，故每拍重放
     * 指定值，确保 500 ms 刷新读到的是巡页要取证的值（板端无此路径）。 */
    if (s_tour_hr_bpm > 0) {
        bicycle_runtime_update_sensors((uint16_t)s_tour_hr_bpm, true,
                                       (uint16_t)s_tour_cad_rpm, true, 0, false);
    }

    switch (st->kind) {
        case TOUR_ST_BOOT:
            s_tour.boot_wait++;
            if (tour_boot_ready()) {
                tour_log("boot: splash finished, page=%s, waited %d ticks (%u ms virtual)",
                         tour_page_name((int)lvgl_page_current_id()),
                         s_tour.boot_wait, (unsigned)s_tour.boot_wait * TOUR_TIMER_MS);
                tour_next_step();
            } else if (s_tour.boot_wait >= TOUR_BOOT_TIMEOUT) {
                tour_log("boot: timeout after %d ticks, current page=%s (continue)",
                         s_tour.boot_wait,
                         tour_page_name((int)lvgl_page_current_id()));
                tour_next_step();
            }
            return;

        case TOUR_ST_OPEN: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur == st->arg) {
                tour_log("open %s: already current, skip", tour_page_name(st->arg));
            } else {
                int rc = lv_pm_open_page_msg((lv_pm_id)st->arg, LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("open %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("open %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    tour_finish();
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_CLOSE: {
            bicycle_pm_id_t cur = lvgl_page_current_id();

            if ((int)cur != st->arg) {
                tour_log("close %s: not current (now %s), skip",
                         tour_page_name(st->arg), tour_page_name((int)cur));
            } else {
                int rc = lv_pm_close_page_msg(LV_PM_MSG_NONE);

                if (rc == 0) {
                    tour_log("close %s: ok", tour_page_name(st->arg));
                } else {
                    tour_log("close %s: FAILED rc=%d", tour_page_name(st->arg), rc);
                    s_tour.failed = true;
                    tour_finish();
                    return;
                }
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_THEME:
            if (lvgl_page_theme_set_by_name(st->name)) {
                tour_log("theme -> %s (now %s)", st->name, lvgl_page_theme_name());
            } else {
                tour_log("theme -> %s: FAILED (now %s)", st->name,
                         lvgl_page_theme_name());
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_DEMO_PAGE:
            if (st->name != NULL && helm_shell_demo_page(st->name)) {
                tour_log("demo page -> %s (current=%s)", st->name,
                         tour_page_name((int)lvgl_page_current_id()));
            } else {
                tour_log("demo page -> %s: FAILED", st->name ? st->name : "(null)");
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RING:
            helm_shell_demo_ring(st->arg);

            helm_shell_demo_ring(st->arg);
            tour_log("demo ring mode=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RING_STYLE:
            helm_shell_demo_ring_style(st->arg);
            tour_log("demo ring style=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_RIDE:
            helm_shell_demo_ride((float)st->arg / 10.0f);
            tour_log("demo ride speed=%.1f", (double)st->arg / 10.0);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_PAUSE:
            helm_shell_demo_pause(st->arg != 0);
            tour_log("demo pause=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_BOTTOM:
            helm_shell_demo_bottom(st->arg);
            tour_log("demo bottom=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DEMO_BANNER:
            helm_shell_demo_banner(st->arg);
            tour_log("demo banner=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DUMP_RIDE:
            helm_shell_demo_ride_dump();
            tour_next_step();
            return;

        case TOUR_ST_KEY:
            /* arg: 1/2 = KEY1/KEY2 短按；11/12 = 长按。 */
            helm_shell_demo_key(st->arg % 10, st->arg >= 10);
            tour_log("key inject KEY%d %s", st->arg % 10,
                     st->arg >= 10 ? "long" : "short");
            tour_next_step();
            return;

        case TOUR_ST_MENU_KEY:
            /* arg: 1/2 = KEY1/KEY2 短按；11/12 = 长按；21 = KEY1 双击。 */
            tour_log("key inject menu KEY%d kind=%d radio=%d", st->arg % 10,
                     st->arg / 10, myvendor_devctl_radio_get() ? 1 : 0);
            helm_menu_demo_key(st->arg % 10, st->arg / 10);
            tour_next_step();
            return;

        case TOUR_ST_MENU_DUMP:
            helm_menu_demo_key(0, 0);
            tour_log("menu dump radio=%d",
                     myvendor_devctl_radio_get() ? 1 : 0);
            tour_next_step();
            return;

        case TOUR_ST_PWR:
            /* arg: 1=单击 2=双击 3=长按 2s 4=取消确认框（真 helm_pwr 状态机）。 */
            tour_log("pwr inject %d", st->arg);
            helm_pwr_demo_action(st->arg);
            tour_next_step();
            return;

        case TOUR_ST_PWR_DUMP:
            helm_pwr_demo_dump();
            tour_next_step();
            return;

        case TOUR_ST_SAVE_DUMP:
            helm_shell_demo_save_dump();
            tour_next_step();
            return;

        case TOUR_ST_NAV_GPX: {
            const char * path = (st->name != NULL && st->name[0] != '\0')
                ? st->name : getenv("SIM_CLIMB_GPX");
            map_page_t * page = lvgl_page_map();
            bool ok;

            if (path == NULL || path[0] == '\0') {
                path = SIM_CLIMB_GPX_DEFAULT;
            }
            ok = (page != NULL) && map_page_nav_from_gpx(page, path, false);
            tour_log("nav gpx %s -> %s", path, ok ? "ok" : "FAILED");
            if (!ok) {
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_CLIMB_DUMP:
            tour_climb_dump();
            tour_next_step();
            return;

        case TOUR_ST_DEMO_ENV:
            /* 真 runtime 入口：录制中 update_env 才把 dalt 记进 gain。
             * 同一拍里立刻走一次 helm_shell_demo_page("climb") 的同步刷新 + dump：
             * 地图页的 gpx 定时器（200 ms）会用 env 把 grade 写回 0（模拟器没有
             * IMU），隔拍再读就看不到 3.4% 了。 */
            bicycle_runtime_set_recording(true);
            bicycle_runtime_update_env(500.0f, true,
                (float)st->arg / 10.0f, 12.0f);
            (void)helm_shell_demo_page("climb");
            tour_log("demo env grade=%.1f%% gain=12m alt=500m rec=1",
                     (double)st->arg / 10.0);
            tour_climb_dump();
            tour_next_step();
            return;

        case TOUR_ST_DIAL_PAUSE:
            helm_shell_demo_dial_pause(st->arg != 0);
            tour_log("dial pause=%d", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DIAL_DUMP:
            helm_shell_demo_dial_dump();
            tour_next_step();
            return;

        case TOUR_ST_NAV_SPEED:
            /* 路线 sim 的速度：配置 + 已在跑的 sim 同步改（R1-S10 取证用）。 */
            bicycle_config_set_nav_sim_speed_kph((float)st->arg / 10.0f);
            bicycle_route_sim_set_speed((float)st->arg / 10.0f);
            tour_log("nav sim speed=%.1f", (double)st->arg / 10.0);
            tour_next_step();
            return;

        case TOUR_ST_RT_SENSORS:
            s_tour_hr_bpm = st->arg;
            s_tour_cad_rpm = 92;
            bicycle_runtime_update_sensors((uint16_t)st->arg, true, 92, true,
                                           0, false);
            (void)helm_shell_refresh();
            tour_log("rt sensors hr=%d cad=92", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_GNSS_SIM: {
            map_page_t *page = lvgl_page_map();
            const char *path = (st->name != NULL && st->name[0] != '\0')
                ? st->name : SIM_CLIMB_GPX_DEFAULT;
            int rc = map_page_gnss_sim(page, path, false,
                                       (float)st->arg / 10.0f, 0.0f);

            tour_log("gnss sim %s speed=%.1f -> %d", path,
                     (double)st->arg / 10.0, rc);
            if (rc != 0) {
                s_tour.failed = true;
                tour_finish();
                return;
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_SEED:
            bicycle_runtime_seed_session(12300.0, 1522000ull);
            (void)helm_shell_refresh();
            tour_log("seed 12.3km / 25:22");
            tour_next_step();
            return;

        case TOUR_ST_DIAL_SNAP: {
            /* 同一拍里：改 runtime → 刷新 → dump → 整屏截图。避免 500 ms
             * 定时器在中间把心率换回板级桩的 128（R1-S10 取证专用）。
             * arg2 = 心率（0 则不覆盖，保留桩的 128）。 */
            bicycle_runtime_t *drt =
                (bicycle_runtime_t *)(uintptr_t)bicycle_runtime_get();

            if (drt != NULL) {
                drt->speed_kph = (float)st->arg / 10.0f;
                if (st->arg2 > 0) {
                    drt->hr_bpm = (uint16_t)st->arg2;
                    drt->hr_valid = true;
                    drt->hr_avg_bpm = (uint16_t)(st->arg2 - 3);
                    drt->hr_max_bpm = (uint16_t)(st->arg2 + 2);
                    drt->cadence_rpm = 92;
                    drt->cadence_valid = true;
                    s_tour_hr_bpm = st->arg2;
                    s_tour_cad_rpm = 92;
                }
            }
            (void)helm_shell_refresh();
            helm_shell_demo_dial_dump();
            if (st->name != NULL) {
                tour_take_shot(st->name);
            }
            tour_log("dial snap speed=%.1f hr=%d", (double)st->arg / 10.0,
                     st->arg2);
            tour_next_step();
            return;
        }

        case TOUR_ST_SB_SNAP: {
            /* R1-S11：同一拍里把状态栏要读的所有状态改完 → 强制刷新 →
             * 截图（1 s 轮询/服务定时器来不及覆盖）。arg2 位：
             *   1 = 录制中、2 = 暂停、4 = 关蓝牙、8 = 关传感器、16 = GPS 失联。
             * 暂停走 helm_shell_demo_dial_pause（只置 s_sh.paused，收起暂停
             * 条），让 REC 直接取灰点，不引入覆盖层。 */
            bicycle_runtime_t *drt =
                (bicycle_runtime_t *)(uintptr_t)bicycle_runtime_get();
            const int flags = st->arg2;
            const bool rec = (flags & 1) != 0;
            const bool paused = (flags & 2) != 0;
            const bool radio = (flags & 4) == 0;
            const bool sensor = (flags & 8) == 0;
            const bool gnss_alive = (flags & 16) == 0;

            if (drt != NULL) {
                drt->recording = rec;
                drt->gnss_alive = gnss_alive;
                drt->gnss_valid = gnss_alive;
                if (gnss_alive) {
                    drt->gnss_fix_quality = 2;
                    drt->gnss_satellites = 9;
                    drt->gnss_hdop_x10 = 8;
                }
            }
            (void)myvendor_devctl_radio_set(radio);
            (void)myvendor_devctl_sensor_set(sensor);
            helm_shell_demo_dial_pause(paused);
            bicycle_status_bar_demo_battery(st->arg);
            bicycle_status_bar_refresh();
            if (st->name != NULL) {
                tour_take_shot(st->name);
            }
            tour_log("sb snap %s batt=%d flags=0x%02x rec=%d paused=%d "
                     "radio=%d sensor=%d gps=%d",
                     st->name != NULL ? st->name : "(keep)", st->arg, flags,
                     rec ? 1 : 0, paused ? 1 : 0, radio ? 1 : 0,
                     sensor ? 1 : 0, gnss_alive ? 1 : 0);
            tour_next_step();
            return;
        }

        case TOUR_ST_WAIT:
            if (st->arg > 0) {
                usleep((useconds_t)st->arg * 1000u);
            }
            tour_log("wait %d ms (real)", st->arg);
            tour_next_step();
            return;

        case TOUR_ST_DUMP:
            helm_shell_demo_ring_dump();
            tour_next_step();
            return;

        case TOUR_ST_SETTLE: {
            /* arg > 0：本步固定帧数；arg < 0：上限（不超过 --tour-frames）。 */
            int frames = s_tour.frames;

            if (st->arg > 0) {
                frames = st->arg;
            } else if (st->arg < 0 && frames > -st->arg) {
                frames = -st->arg;
            }

            /* 转场动画没完先等它；卡死就 drain（与板端抢占策略一致）。 */
            if (lv_pm_nav_busy()) {
                s_tour.nav_wait++;
                if (s_tour.nav_wait >= TOUR_NAV_TIMEOUT) {
                    tour_log("settle: nav busy %d ticks, drain", s_tour.nav_wait);
                    lv_pm_nav_drain();
                    s_tour.nav_wait = 0;
                    s_tour.waited = 0;
                }
                return;
            }

            if (s_tour.waited < frames) {
                s_tour.waited++;
                return;
            }
            tour_next_step();
            return;
        }

        case TOUR_ST_SHOT:
            tour_take_shot(st->name);
            tour_next_step();
            return;

        case TOUR_ST_MTP:
            sim_ui_mtp_force_attached = (st->arg != 0);
            tour_log("mtp stub: %s", sim_ui_mtp_force_attached ? "host attached" : "host off");
            tour_next_step();
            return;

        case TOUR_ST_DONE:
        default:
            tour_finish();
            return;
    }
}

/**
 * @brief 记录巡页参数（`--ui-tour` / `--tour-frames`）。
 * @note 必须在 `sim_ui_start()` 之前调用（见 `src/scenes.c`）。
 */
void sim_ui_tour_configure(const char *dir, int frames)
{
    s_tour.configured = false;
    if (dir == NULL || dir[0] == '\0') {
        return;
    }
    if (strlen(dir) >= sizeof(s_tour.dir)) {
        fprintf(stderr, "[tour] dir too long, disabled: %s\n", dir);
        return;
    }
    strcpy(s_tour.dir, dir);
    s_tour.frames = (frames > 0) ? frames : 90;
    s_tour.configured = true;

    /* WP-HELM10/R1-S2：环形主页专用剧本（env 选择，默认剧本不变）。 */
    {
        const char *script = getenv("SIM_UI_TOUR_SCRIPT");

        if (script != NULL && strcmp(script, "ring") == 0) {
            s_steps = kRingSteps;
            s_step_count = TOUR_STEP_COUNT_RING;
            fprintf(stderr, "[tour] script=ring steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "ring_ride") == 0) {
            s_steps = kRingRideSteps;
            s_step_count = TOUR_STEP_COUNT_RING_RIDE;
            fprintf(stderr, "[tour] script=ring_ride steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "ring_anim") == 0) {
            s_steps = kRingAnimSteps;
            s_step_count = TOUR_STEP_COUNT_RING_ANIM;
            fprintf(stderr, "[tour] script=ring_anim steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "ring_s8") == 0) {
            s_steps = kRingS8Steps;
            s_step_count = TOUR_STEP_COUNT_RING_S8;
            fprintf(stderr, "[tour] script=ring_s8 steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "ride") == 0) {
            s_steps = kRideSteps;
            s_step_count = TOUR_STEP_COUNT_RIDE;
            fprintf(stderr, "[tour] script=ride steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "map") == 0) {
            s_steps = kMapSteps;
            s_step_count = TOUR_STEP_COUNT_MAP;
            fprintf(stderr, "[tour] script=map steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "keys") == 0) {
            s_steps = kKeysSteps;
            s_step_count = TOUR_STEP_COUNT_KEYS;
            fprintf(stderr, "[tour] script=keys steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "s4b") == 0) {
            s_steps = kS4bSteps;
            s_step_count = TOUR_STEP_COUNT_S4B;
            fprintf(stderr, "[tour] script=s4b steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "climb") == 0) {
            s_steps = kClimbSteps;
            s_step_count = TOUR_STEP_COUNT_CLIMB;
            fprintf(stderr, "[tour] script=climb steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "dial") == 0) {
            s_steps = kDialSteps;
            s_step_count = TOUR_STEP_COUNT_DIAL;
            fprintf(stderr, "[tour] script=dial steps=%d\n", s_step_count);
        } else if (script != NULL && strcmp(script, "s11") == 0) {
            s_steps = kS11Steps;
            s_step_count = TOUR_STEP_COUNT_S11;
            fprintf(stderr, "[tour] script=s11 steps=%d\n", s_step_count);
        } else {
            s_steps = TOUR_STEPS_DEFAULT;
            s_step_count = TOUR_STEP_COUNT_DEFAULT;
        }
    }
}

/**
 * @brief 开机序列跑完后启动巡页（由 ui_boot.c 在末尾调用）。
 */
void sim_ui_tour_start(void)
{
    if (!s_tour.configured || s_tour.started) {
        return;
    }
    s_tour.started = true;

    if (!tour_mkdir_p(s_tour.dir)) {
        fprintf(stderr, "[tour] cannot create dir %s: %s\n", s_tour.dir,
                strerror(errno));
        s_tour.failed = true;
        return;
    }

    tour_log("start dir=%s frames=%d steps=%d", s_tour.dir, s_tour.frames,
             s_step_count);
    s_tour.tmr = lv_timer_create(tour_tick_cb, TOUR_TIMER_MS, NULL);
    if (!s_tour.tmr) {
        fprintf(stderr, "[tour] cannot create timer\n");
        s_tour.failed = true;
    }
}

/**
 * @brief 巡页是否已经结束（headless 主循环据此提前退出）。
 */
bool sim_ui_tour_done(void)
{
    return s_tour.done || s_tour.failed;
}

