/**
 * @brief 演示：直接显示指定页面（UI 线程）。
 * @details 名字映射到固定页并加页面锁，`helm_page_at()` 之后恒返回该页；
 *          同时把活动 index 挪到轮转表里对应的槽位（海拔页的采样槽靠
 *          `helm_active_idx()` 取，必须落在 CLIMB 槽）。任意翻页键会清掉锁，
 *          恢复正常轮转。
 */
bool helm_shell_demo_page(const char * name)
{
    helm_page_id_t id;
    uint8_t * idx;

    if (name == NULL) {
        return false;
    }

    if (strcmp(name, "standby") == 0) {
        id = HELM_PAGE_STANDBY;
    } else if (strcmp(name, "ride") == 0) {
        id = HELM_PAGE_DATA;
    } else if (strcmp(name, "data") == 0) {
        id = HELM_PAGE_DATA_ALL;
    } else if (strcmp(name, "map") == 0) {
        id = HELM_PAGE_MAP;
    } else if (strcmp(name, "turn") == 0) {
        id = HELM_PAGE_TURN;
    } else if (strcmp(name, "climb") == 0) {
        id = HELM_PAGE_CLIMB;
    } else {
        return false;
    }

    s_demo_page = id;
    idx = helm_active_idx();
    if (helm_in_session()) {
        /* 骑行轮转：骑行页 / 数据页 / 地图页 / 海拔页。 */
        switch (id) {
        case HELM_PAGE_DATA_ALL:
            *idx = 1;
            break;
        case HELM_PAGE_MAP:
            *idx = 2;
            break;
        case HELM_PAGE_CLIMB:
            *idx = 3;
            break;
        default:
            *idx = 0;
            break;
        }
    } else {
        /* 待机轮转：主页面 / 骑行页 / 数据页；其余页没有槽位，退回 0。 */
        switch (id) {
        case HELM_PAGE_DATA:
            *idx = 1;
            break;
        case HELM_PAGE_DATA_ALL:
            *idx = 2;
            break;
        default:
            *idx = 0;
            break;
        }
    }

    s_sh.view_anim = false;
    helm_apply_view();
    helm_refresh_numbers();
    helm_raise_chrome();
    return true;
}

/** @brief 演示：清除页面锁，恢复正常轮转。 */
void helm_shell_demo_page_clear(void)
{
    s_demo_page = (helm_page_id_t)0xff;
    s_sh.view_anim = false;
    helm_apply_view();
    helm_refresh_numbers();
    helm_raise_chrome();
}

