static void helm_on_menu(void * ud)
{
    LV_UNUSED(ud);
    if (!s_sh.attached) {
        return;
    }

    /* 任意按键都算"有交互"：把待机页提示环的浮动重新叫醒（3 s 后再自停）。 */
    helm_sb_bob_kick();

    if (helm_save_open()) {
        helm_save_hide();
        myvendor_sound_back();
        return;
    }

    if (helm_arrive_open()) {
        helm_arrive_confirm();
        myvendor_sound_back();
        return;
    }

    if (s_sh.paused) {
        printf("helm: KEY1 long menu (paused)\n");
        myvendor_sound_long();
        if (helm_menu_open() != 0) {
            printf("helm: menu open failed\n");
        }
        return;
    }

    printf("helm: KEY1 long menu\n");
    myvendor_sound_long();
    if (helm_menu_open() != 0) {
        printf("helm: menu open failed\n");
    }
}

